+      '```python',
+      `page.get_by_role("button", name="Submit").click()`,
+    ].join('\n')),
+  });
+});
+
+test('start twice is an error', async ({ client, server }) => {
+  await navigateToForm(client, server);
+  await client.callTool({ name: 'browser_start_recording' });
