+				approver.shouldAutoApprove('Get-ChildItem; Remove-Item x', { language: 'powershell', autoApproveRules: deniedSubCommand }),
+			], ['noMatch', 'denied', 'noMatch', 'noMatch', 'denied']);
+		});
