+
+	test('surfaces deferred endpoint resolution failures and allows retry', async () => {
+		const ipc = ds.add(new FakeIPCServer());
+		let resolveCount = 0;
+		const channel = ds.add(new AgentHostChannel<string>(
+			ipc as unknown as IPCServer<string>,
+			async () => {
+				resolveCount++;
+				if (resolveCount === 1) {
