+	if (!command) {
+		return undefined;
+	}
+	return {
+		kind: 'command',
+		commandId: command.commandId,
+		confidence: Math.max(0, Math.min(1, record.confidence)),
+		reason: typeof record.reason === 'string' ? record.reason : undefined,
+	};
