+			}),
+			['', indicator(INDICATOR_LEFT), '', '', '', '']
+		);
+	});
+
+	test('renders nothing before prepareRender has run', () => {
+		assert.deepStrictEqual(
+			renderIndicators(WRAPPED_TEXT, { ...WRAPPING_OPTIONS, wordWrapIndicator: true }, { skipPrepareRender: true }),
+			['', '', '', '', '', '']
+		);
+	});
