+				await configuration.setUserConfiguration(AGENT_SESSIONS_STORAGE_CLEANUP_SUGGESTION_SETTING, false);
+				return ByteSize.GB;
+			},
+		});
+		await timeout(10_001);
+		contribution.dispose();
+		assert.deepStrictEqual(availableSpace, []);
+	}));
+});
